import os

from main import parse_donation_created_event
from similarity_embedding import (
    logger as similarity_embedding_logger,
)
from langchain.globals import set_debug
from typesense_client import TypesenseClient
from cloudevents.http.event import CloudEvent
import json
import logging
from enrich_donations import enrich_donation, enriched_donation_to_typesense_doc

if __name__ == "__main__":
    set_debug(True)
    # TODO(SF) debug logging not visible
    logging.getLogger(__name__).setLevel(logging.DEBUG)
    logging.getLogger(name=similarity_embedding_logger.name).setLevel(logging.DEBUG)

    event_json = json.loads(
        '{"attributes": {"id": "15657351798383557", "time": "2025-08-21T12:16:29.334Z", "specversion": "1.0", "datacontenttype": "application/json", "type": "google.cloud.pubsub.topic.v1.messagePublished", "source": "//pubsub.googleapis.com/"}, "data": {"message": {"@type": "type.googleapis.com/google.pubsub.v1.PubsubMessage", "data": "", "attributes": {"eventType": "DonationCreated", "eventVersion": "1.0.0"}, "messageId": "15657351798383557", "publishTime": "2025-08-21T12:16:29.334Z"}}}'
    )
    event = CloudEvent.create(event_json["attributes"], event_json["data"])
    donation = parse_donation_created_event(event)
    print()  # noqa: T201
    print(donation)  # noqa: T201
    enriched = enrich_donation(donation.data)
    print(enriched)  # noqa: T201
    print()  # noqa: T201
    typesense_doc = enriched_donation_to_typesense_doc(enriched)
    print(typesense_doc.model_dump_json(indent=True))  # noqa: T201
    ts_client = TypesenseClient(
        api_key=json.loads(os.getenv("TYPESENSE_ADMIN_API_KEY")),
        host=json.loads(os.getenv("TYPESENSE_HOST")),
        port=json.loads(os.getenv("TYPESENSE_PORT", "443")),
        protocol=json.loads(os.getenv("TYPESENSE_PROTOCOL")),
        collection_name=json.loads(os.getenv("TYPESENSE_COLLECTION_NAME")),
    )
    ts_client.upsert(typesense_doc.model_dump_json())
